def sabr_phrase(text: str) -> str | None:
    """The first `SABR_PHRASES` entry in `text` as a whole word, else None (`SABR_MATCH`)."""
    folded = text.casefold()
    for phrase in SABR_PHRASES:
        if re.search(rf"\b{re.escape(phrase)}\b", folded):
            return phrase
    return None

